import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/density_editor.C6RRrMf_.svg",y=JSON.parse('{"title":"Density","description":"","frontmatter":{},"headers":[],"relativePath":"generators/DENSITY.md","filePath":"generators/DENSITY.md"}'),o={name:"generators/DENSITY.md"};function i(h,e,d,p,c,l){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="density" tabindex="-1">Density <a class="header-anchor" href="#density" aria-label="Permalink to &quot;Density&quot;">​</a></h1><p>Density keeps a share of a clip&#39;s notes, the strongest places in the bar first: the bar&#39;s start, then its middle, the other beats, the eighths and last the sixteenths. At 100% every note plays, at 50% the sixteenths between the eighths drop out, at 25% only the beats are left, and at 0% nothing. A chord is kept or dropped whole, and drums are thinned too, so one full pattern gives a build, a breakdown or a fill. Density is one of the three shapes, each a percentage that ramps from a start to an end, which <a href="./../GENERATORS#shapes">Generators</a> describes: where each is set, which wins, and the settings they share. The Density percentage runs from 0% to 100%.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+r+'" alt="A Density generator&#39;s settings"></p><p>The settings are those every shape shares, which <a href="./../GENERATORS#shapes">Generators</a> describes.</p><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Set Density in the <code>+ Density</code> section of a Scene page or a clip page, or make a Density generator and add it to a chain, as <code>density: name</code>, to paint one shape on many clips and change it in one place. <code>examples/by_genre/electronic/edm_density.yml</code> builds and breaks down an EDM track by Density alone.</p>',7)])])}const _=t(o,[["render",i]]);export{y as __pageData,_ as default};
